  "gabarito": "E",
  "comentario": "**Gabarito: E.** **Empatia** é colocar-se no lugar do outro para entender seu ponto de vista e suas emoções. Ser empático não obriga a atender a pedidos indevidos: é possível compreender a frustração e, ao mesmo tempo, explicar limites.\n\n- Concordar com tudo é submissão, não empatia.\n- Pena e concessões fora da norma não são empatia e geram risco.\n- Espelhar um cliente exaltado tende a escalar o conflito.\n- Sorrir é simpatia/cordialidade; empatia exige compreensão do problema.",
