  "enunciado": "Considere as seguintes práticas no atendimento por chat do banco.\n\nI. Usar linguagem clara e cordial, evitando textos em letras maiúsculas, que podem soar como grito.\nII. Informar ao cliente, quando a solução depender de outra área, o prazo e a forma de retorno.\nIII. Solicitar a senha da conta pelo chat para agilizar a validação da identidade do cliente.\n\nSão boas práticas de atendimento digital as indicadas em",
