  "comentario": "**Gabarito: E.** **I** correta: no texto, maiúsculas e tom seco são lidos como agressividade; a clareza é essencial. **II** correta: transparência sobre prazos e retorno reduz ansiedade e recontatos. **III** errada: o banco **nunca** deve solicitar senha ao cliente por chat, telefone ou e-mail; isso contraria regras de segurança e é justamente o que golpistas fazem.\n\nPor isso, qualquer alternativa que inclua III ou exclua I ou II está errada.",
