  "texto_base": null,
  "enunciado": "Durante uma conversa com uma comerciante, o atendente pergunta: “Se as vendas no cartão continuarem demorando 30 dias para cair na conta, como isso afeta o pagamento dos seus fornecedores?”. No método SPIN, essa é uma pergunta de",
