  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Um cliente que acaba de financiar um veículo recebe a oferta de um seguro auto adequado ao bem financiado, de livre escolha e com a possibilidade de contratar em outra seguradora. Já outro cliente, que tem conta básica, é orientado a migrar para um pacote mais completo porque passou a usar mais serviços. Essas situações exemplificam, respectivamente,",
