  "enunciado": "Um gerente percebe que, ao apresentar um investimento, falou durante vinte minutos sobre as características técnicas do produto, e o cliente perdeu o interesse. Segundo a técnica CVB (características, vantagens e benefícios), o mais eficaz seria",
