  "gabarito": "B",
  "comentario": "**Gabarito: B.** Na técnica **CVB**, a **característica** é o que o produto é (ex.: liquidez diária), a **vantagem** é o que ela permite (resgatar quando quiser) e o **benefício** é o ganho para aquele cliente (ter a reserva disponível numa emergência). Clientes compram benefícios.\n\n- Mais detalhe técnico agrava o problema.\n- Omitir características prejudica a informação clara.\n- Excesso de opções confunde.\n- Falar mal da concorrência é antiético e não mostra valor próprio.",
