  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Em um ano, uma carteira começou com 800 clientes e, ao longo do período, 48 deles encerraram o relacionamento. Considerando apenas esses dados, a taxa de churn (evasão) anual da carteira foi de",
  "imagem": null,
  "alternativas": {
    "A": "8%.",
    "B": "94%.",
    "C": "6%.",
    "D": "4,8%.",
    "E": "5,6%."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** **Churn** = clientes perdidos ÷ clientes no início do período = 48 ÷ 800 = 0,06 = **6%**. A taxa de retenção correspondente seria 94%, que é o complemento, e não o churn.\n\n- 4,8% resulta de dividir 48 por 1.000.\n- 5,6% e 8% não decorrem dos dados.\n- 94% é a retenção, não a evasão.",
  "tags": [
    "tecnico-bancario",
    "churn",
    "calculo"
  ],
  "embaralhavel": true,
  "status": "validada",
