  "comentario": "**Gabarito: A.** O livro *Como chegar ao sim* (Fisher, Ury e Patton) propõe quatro princípios: **separar as pessoas do problema**, **focar em interesses e não em posições**, **criar opções de ganho mútuo** e **usar critérios objetivos**. É a base da negociação **ganha-ganha**.\n\n- A primeira lista descreve barganha posicional dura.\n- A segunda é o oposto do método.\n- A terceira descreve a negociação “branda”, que o método também critica.\n- A quarta descreve submissão, não negociação por princípios.",
