  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Uma cliente exige “desconto de 50% na tarifa”. Ao conversar, o atendente descobre que sua preocupação real é o custo mensal total da conta, que subiu com o uso de serviços avulsos. Pelo método de Harvard, a atitude do atendente que melhor aplica o princípio de focar em interesses é",
