  "comentario": "**Gabarito: C.** **Posição** é o que a parte diz querer (50% de desconto); **interesse** é o motivo por trás (pagar menos por mês). Ao atender o interesse, surgem soluções que a posição esconde.\n\n- Recusar se prende à posição e encerra a negociação.\n- Ceder à posição pode ser indevido e não necessariamente resolve o problema.\n- Dividir a diferença é barganha posicional.\n- Transferir não resolve e não aplica o método.",
