  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Na venda de um imóvel retomado, o banco aceita, no mínimo, R$ 180.000,00, e o comprador está disposto a pagar, no máximo, R$ 210.000,00. Nessas condições, a zona de possível acordo (ZOPA) corresponde ao intervalo entre",
  "imagem": null,
  "alternativas": {
    "A": "R$ 0,00 e R$ 180.000,00, com amplitude de R$ 180.000,00.",
    "B": "R$ 195.000,00 e R$ 210.000,00, com amplitude de R$ 15.000,00.",
    "C": "R$ 210.000,00 e R$ 240.000,00, com amplitude de R$ 30.000,00.",
    "D": "não há ZOPA, porque o preço mínimo do vendedor é menor que o máximo do comprador.",
    "E": "R$ 180.000,00 e R$ 210.000,00, com amplitude de R$ 30.000,00."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** A **ZOPA** é a faixa entre o **valor de reserva do vendedor** (mínimo que aceita) e o **valor de reserva do comprador** (máximo que paga). Existe acordo possível porque 180 mil < 210 mil; a amplitude é 210.000 − 180.000 = **R$ 30.000,00**.\n\n- Abaixo de 180 mil o vendedor não aceita.\n- Começar em 195 mil corta indevidamente metade da faixa.\n- Acima de 210 mil o comprador não paga.\n- A ZOPA existe justamente quando o mínimo do vendedor é menor que o máximo do comprador.",
