  "gabarito": "B",
  "comentario": "**Gabarito: B.** Na **distributiva** (ganha-perde, soma zero), discute-se como “repartir o bolo”, geralmente um só item, como preço. Na **integrativa** (ganha-ganha), as partes exploram interesses e múltiplas variáveis para “aumentar o bolo”.\n\n- Ampliar valor e ganhos mútuos é característica da integrativa.\n- Na distributiva há conflito direto de interesses.\n- Relacionamento de longo prazo é mais típico da integrativa.\n- Na distributiva, as partes costumam proteger seus limites.",
