  "enunciado": "Uma empresa cliente pede redução da taxa de um capital de giro. O gerente, em vez de discutir só a taxa, propõe ajustar o prazo, oferecer domicílio bancário das vendas com cartão e incluir a folha de pagamento, o que reduz o risco para o banco e permite melhor taxa para a empresa. Essa abordagem caracteriza a negociação",
