    "B": "distributiva, pois a discussão envolve taxa de juros.",
    "C": "posicional, pois o gerente se mantém fixo na taxa original.",
    "D": "integrativa, pois amplia as variáveis negociadas para gerar valor a ambas as partes.",
    "E": "por evitação, pois o gerente se esquiva do pedido de redução da taxa."
