  "gabarito": "D",
  "comentario": "**Gabarito: D.** Ao incluir mais variáveis (prazo, domicílio, folha), o gerente cria **trocas de valor**: o banco reduz risco e amplia relacionamento, e a empresa obtém taxa melhor. É a lógica **integrativa** (ganha-ganha).\n\n- A presença de taxa não torna a negociação distributiva; o que importa é a busca de valor conjunto.\n- Não há rigidez na taxa original.\n- O gerente não se esquiva; enfrenta o pedido com alternativas.\n- Não houve concessão integral.",
