  "enunciado": "Ao renegociar uma dívida, cliente e banco divergem sobre o valor justo da parcela. O atendente propõe que o cálculo seja feito com base no comprometimento de renda comprovado e nas condições vigentes das linhas de renegociação, iguais para todos os clientes. Ele está aplicando o princípio de",
