BANCO.push({
  "id": "TB-VNA-0067",
  "concursos": [
    "banestes-2026-tecnico-bancario"
  ],
  "banca_estilo": "FCC",
  "bloco": "especificos",
  "materia": "Vendas, Negociação e Atendimento",
  "eixo": null,
  "topico": "Negociação: conceitos, etapas, estratégias e técnicas",
  "ref_apostila": null,
  "origem": {
    "tipo": "simulado",
    "fonte": "Inédita Técnico Bancário (nov/2026)",
    "id_pai": null,
    "anulada": false
  },
  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre estilos de administração de conflitos, conforme o modelo de Thomas-Kilmann.\n\nI. No estilo colaboração, busca-se uma solução que satisfaça plenamente os interesses de ambas as partes.\nII. No estilo acomodação, a pessoa abre mão dos próprios interesses para satisfazer os do outro.\nIII. No estilo competição, a pessoa busca dividir igualmente os ganhos, cedendo em parte.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I e II, apenas.",
    "B": "I, apenas.",
    "C": "III, apenas.",
    "D": "II e III, apenas.",
    "E": "I, II e III."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** O modelo de Thomas-Kilmann tem cinco estilos: **competição** (assertivo e pouco cooperativo — impor), **colaboração** (assertivo e cooperativo — ganha-ganha), **compromisso** (ceder em parte, dividir), **evitação** (pouco assertivo e pouco cooperativo) e **acomodação** (cooperativo e pouco assertivo — ceder).\n\n**I** e **II** corretas. **III** errada: dividir e ceder em parte descreve o **compromisso**, não a competição.",
  "tags": [
    "tecnico-bancario",
    "thomas-kilmann",
    "conflitos"
  ],
  "embaralhavel": true,
  "status": "validada",
  "validacao": {
    "por": "autor",
    "em": "2026-11-17",
    "obs": "Inédita para o Técnico Bancário; conferida pelo autor."
  },
  "versao": 1
});

