  "texto_base": null,
  "enunciado": "Um banco desenhou o mapa da jornada do cliente na contratação de crédito imobiliário, identificando cada etapa, ponto de contato, emoção do cliente e momento de frustração. O principal objetivo desse mapeamento é",
  "imagem": null,
  "alternativas": {
    "A": "calcular a taxa de juros mais adequada para cada cliente.",
    "B": "substituir as pesquisas de satisfação, que se tornam desnecessárias.",
    "C": "definir as metas individuais de venda dos gerentes.",
    "D": "eliminar todos os contatos humanos do processo.",
    "E": "identificar pontos de dor e oportunidades de melhoria sob a ótica do cliente."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** O **mapa da jornada** (*customer journey map*) descreve, do ponto de vista do cliente, as etapas, pontos de contato e emoções, revelando **pontos de dor** e “momentos da verdade” a melhorar.\n\n- Precificação é análise de crédito e mercado.\n- Pesquisas continuam úteis e alimentam o mapa.\n- Metas de vendas são outro instrumento de gestão.\n- O mapeamento pode até mostrar onde o contato humano é mais valorizado.",
  "tags": [
    "tecnico-bancario",
    "jornada",
    "cx"
  ],
  "embaralhavel": true,
