  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre marketing de relacionamento.\n\nI. Seu foco está na criação de valor para o cliente e em relações de longo prazo, e não apenas em transações isoladas.\nII. A confiança e o comprometimento mútuos são elementos centrais do relacionamento.\nIII. Por ser voltado para o longo prazo, dispensa a coleta e o uso de informações sobre os clientes.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I e II, apenas.",
    "B": "I, apenas.",
    "C": "II, apenas.",
    "D": "I e III, apenas.",
    "E": "I, II e III."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** **I** e **II** corretas: o marketing de relacionamento busca relações duradouras e mutuamente benéficas, baseadas em **confiança** e **comprometimento**. **III** errada: ele depende fortemente de **informação** sobre o cliente (CRM, bancos de dados) para personalizar o relacionamento.\n\nPor isso, as combinações com III ou sem I e II estão erradas.",
  "tags": [
    "tecnico-bancario",
    "marketing-relacionamento"
  ],
