  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Na avaliação de perfil do investidor (API), um cliente foi classificado como conservador, mas pede para aplicar parte relevante do patrimônio em um fundo de ações. Segundo as boas práticas de adequação, o atendente deve",
  "imagem": null,
  "alternativas": {
    "A": "sugerir que o cliente faça a aplicação em nome de um parente com perfil arrojado.",
    "B": "recusar a aplicação, pois o cliente conservador está proibido de investir em renda variável.",
    "C": "realizar a aplicação sem qualquer comentário, pois a decisão final de investir é sempre do cliente.",
    "D": "alertá-lo sobre a inadequação e, se ele quiser prosseguir por conta própria, obter sua declaração de ciência.",
    "E": "alterar o perfil do cliente no sistema para arrojado, a fim de liberar a operação."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** A regra de adequação **veda recomendar** produto inadequado, mas não proíbe o cliente de investir por conta própria. Nesse caso, a instituição deve **alertá-lo** e obter **declaração expressa** de que está ciente da inadequação.\n\n- Não há proibição absoluta de investir.\n- Executar sem alertar descumpre o dever de adequação.\n- Alterar o perfil sem nova avaliação real é fraude ao processo.\n- Usar terceiro para burlar o perfil é conduta antiética.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "suitability",
    "api"
  ],
  "embaralhavel": true,
  "status": "validada",
