  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre a avaliação do perfil do investidor.\n\nI. O perfil deve ser atualizado periodicamente, pois a situação financeira e os objetivos do cliente podem mudar.\nII. A avaliação considera, entre outros fatores, o horizonte de investimento e a tolerância a perdas.\nIII. Uma vez definido o perfil, o banco pode recomendar qualquer produto, já que a avaliação foi feita.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I e II, apenas.",
    "B": "I, apenas.",
    "C": "II, apenas.",
    "D": "II e III, apenas.",
    "E": "I, II e III."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** **I** correta: mudanças de renda, idade e objetivos exigem **atualização** periódica do perfil. **II** correta: horizonte, objetivos, tolerância a risco/perdas, situação financeira e conhecimento compõem a avaliação. **III** errada: o perfil serve justamente para limitar as recomendações aos produtos **compatíveis** com ele.\n\nAs combinações com III ou sem I e II estão erradas.\n\nRevisar: Apostila 03, §17.",
