  "texto_base": null,
  "enunciado": "Um cliente quer investir para uma viagem que fará em seis meses e não aceita correr o risco de ter menos dinheiro do que aplicou. Entre as opções abaixo, a mais coerente com seu objetivo e prazo é",
  "imagem": null,
