  "comentario": "**Gabarito: E.** A **Ouvidoria** é componente da própria instituição e atua como **segunda (e última) instância interna**: recebe demandas não resolvidas no atendimento primário (agência, SAC, canais digitais) e também atua como canal de mediação e de melhoria de processos.\n\n- Solicitações comuns devem ir aos canais primários.\n- A ouvidoria pertence à instituição, não ao Banco Central, e não julga.\n- Ouvidoria e SAC coexistem.\n- Não depende de ação judicial.",
