  "texto_base": null,
  "enunciado": "Segundo a teoria dos dois fatores de Herzberg, aplicada à motivação de equipes comerciais, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "fatores higiênicos, quando adequados, provocam motivação intensa e permanente na equipe.",
    "B": "reconhecimento, responsabilidade e crescimento são fatores motivacionais, e salário e condições de trabalho, higiênicos.",
    "C": "reconhecimento e crescimento profissional são fatores higiênicos, que apenas evitam a insatisfação.",
    "D": "a motivação independe de qualquer fator ligado ao trabalho, sendo apenas traço de personalidade.",
    "E": "salário é o principal fator motivacional, capaz de gerar satisfação duradoura por si só."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** Para **Herzberg**, os **fatores higiênicos** (salário, condições, políticas, supervisão) evitam a insatisfação, mas não motivam por si só. Os **fatores motivacionais** (reconhecimento, realização, responsabilidade, crescimento, o próprio trabalho) geram satisfação e motivação.\n\n- Salário é fator higiênico.\n- Fatores higiênicos apenas evitam a insatisfação.\n- Reconhecimento e crescimento são motivacionais.\n- A teoria liga a motivação justamente a fatores do trabalho.",
