  "comentario": "**Gabarito: A.** Na **SWOT**, **forças** e **fraquezas** são fatores **internos**; **oportunidades** e **ameaças** são fatores **externos**. A fintech concorrente é **ameaça** externa; a nova indústria (potencial de folha de pagamento e novos clientes) é **oportunidade** externa.\n\n- Os dois fatos são externos, não internos.\n- A inversão (oportunidade e ameaça) está errada.\n- Força é fator interno.\n- Não existe “ameaça interna” nem “força externa” na matriz.",
