  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "O princípio segundo o qual as contribuições de um grande número de segurados formam um fundo comum, capaz de pagar os prejuízos dos poucos que efetivamente sofrem sinistros, denomina-se",
  "imagem": null,
  "alternativas": {
    "A": "retrocessão.",
    "B": "princípio da boa-fé.",
    "C": "mutualismo.",
    "D": "princípio indenitário.",
    "E": "sub-rogação."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** O **mutualismo** é a base técnica do seguro: muitos pagam prêmios relativamente pequenos e o fundo formado paga os sinistros de poucos; a lei dos grandes números permite à seguradora estimar essas perdas. O **princípio indenitário** diz que, nos seguros de danos, a indenização não pode superar o prejuízo (o seguro não é fonte de lucro). A **sub-rogação** é a substituição da seguradora, depois de indenizar, nos direitos do segurado contra o causador do dano. A **retrocessão** é a cessão de riscos feita por um ressegurador a outro ressegurador ou a uma seguradora. A **boa-fé** impõe às partes lealdade e veracidade nas informações, e não trata da formação do fundo comum.\n\nRevisar: Apostila 03, §17.",
