  "gabarito": "E",
  "comentario": "**Gabarito: E.** **Sinistro** é a realização do risco coberto, isto é, o evento que gera o direito à indenização. **Prêmio** é o valor que o segurado paga à seguradora pela cobertura. **Franquia** é a parte do prejuízo que fica por conta do segurado. **Endosso** é o documento que altera uma apólice já emitida. **Risco excluído** é o evento que a apólice expressamente não cobre; o enunciado diz que o incêndio estava coberto.\n\nRevisar: Apostila 03, §17.",
