  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Mariana tem seguro de automóvel com franquia de R$ 3.000,00, aplicável a danos parciais. Em uma colisão coberta, o conserto do veículo foi orçado em R$ 7.500,00. Considerando apenas essas informações, a seguradora deverá indenizar",
