  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Uma empresa contrata seguro de vida em grupo para seus empregados, assumindo perante a seguradora a representação do grupo segurado, inclusive o repasse dos prêmios. Nesse contrato, a empresa figura como",
  "imagem": null,
