BANCO.push({
  "id": "TB-CB-0005",
  "concursos": [
    "banestes-2026-tecnico-bancario"
  ],
  "banca_estilo": "FCC",
  "bloco": "especificos",
  "materia": "Conhecimentos Bancários e Securitários",
  "eixo": null,
  "topico": "Seguros: conceitos, princípios e participantes",
  "ref_apostila": {
    "modulo": "03",
    "secao": "17",
    "titulo": "Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966",
    "link": "[[03 - Conhecimentos Bancários e Governança de TIC#17. Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966]]"
  },
  "origem": {
    "tipo": "simulado",
    "fonte": "Inédita Técnico Bancário (nov/2026)",
    "id_pai": null,
    "anulada": false
  },
  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre a distribuição de riscos no mercado de seguros.\n\nI. No cosseguro, duas ou mais seguradoras dividem diretamente um mesmo risco, cada uma responsável por sua cota, normalmente sob a administração de uma seguradora líder.\nII. No resseguro, a seguradora transfere parte de suas responsabilidades a um ressegurador, que passa a responder diretamente ao segurado pelo pagamento das indenizações.\nIII. Retrocessão é a operação pela qual o ressegurador transfere parte dos riscos que aceitou a outros resseguradores ou a seguradoras.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I e III, apenas.",
    "B": "I, apenas.",
    "C": "II, apenas.",
    "D": "I e II, apenas.",
    "E": "I, II e III."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** **I – correta.** O cosseguro é a divisão horizontal do mesmo risco entre seguradoras, com a líder conduzindo a apólice. **II – incorreta.** O resseguro é o “seguro da seguradora”: o segurado contrata e se relaciona apenas com a seguradora, que continua responsável perante ele; o ressegurador responde à seguradora. **III – correta.** Retrocessão é a cessão feita pelo ressegurador. Assim, só I e III estão corretas; as opções que incluem II ou excluem III estão erradas.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "seguros",
    "cosseguro",
    "resseguro"
  ],
  "embaralhavel": true,
  "status": "validada",
  "validacao": {
    "por": "autor",
    "em": "2026-11-17",
    "obs": "Inédita para o Técnico Bancário; conferida pelo autor."
  },
  "versao": 1
});

