BANCO.push({
  "id": "TB-CB-0007",
  "concursos": [
    "banestes-2026-tecnico-bancario"
  ],
  "banca_estilo": "FCC",
  "bloco": "especificos",
  "materia": "Conhecimentos Bancários e Securitários",
  "eixo": null,
  "topico": "Seguros: conceitos, princípios e participantes",
  "ref_apostila": {
    "modulo": "03",
    "secao": "17",
    "titulo": "Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966",
    "link": "[[03 - Conhecimentos Bancários e Governança de TIC#17. Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966]]"
  },
  "origem": {
    "tipo": "simulado",
    "fonte": "Inédita Técnico Bancário (nov/2026)",
    "id_pai": null,
    "anulada": false
  },
  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Ao preencher a proposta de seguro de automóvel, um cliente declara ser o único condutor do veículo, embora saiba que o carro é usado diariamente pelo filho de 19 anos, informação que elevaria o prêmio. Essa conduta",
  "imagem": null,
  "alternativas": {
    "A": "é irrelevante, pois cabe exclusivamente à seguradora verificar, por vistoria, quem dirige o veículo.",
    "B": "viola apenas o princípio do mutualismo, sem qualquer reflexo sobre o direito à indenização.",
    "C": "é permitida, porque o dever de boa-fé no contrato de seguro é imposto somente à seguradora.",
    "D": "só teria consequências se o sinistro fosse causado pelo próprio segurado.",
    "E": "viola o princípio da boa-fé, pois o segurado deve declarar com veracidade as circunstâncias que influem no risco ou no prêmio."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** O contrato de seguro exige **boa-fé e veracidade** de ambas as partes. Omitir ou falsear informação relevante para a análise do risco (como o perfil do condutor principal) pode levar à perda do direito à garantia ou a outras sanções previstas em lei e no contrato. A seguradora pode vistoriar, mas isso não afasta o dever do segurado de declarar a verdade. O problema não é de mutualismo, e a omissão tem, sim, reflexo sobre a indenização. O dever de boa-fé vale para **segurado e seguradora**. A omissão contamina a avaliação do risco como um todo, e não só os sinistros causados pelo próprio segurado.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "seguros",
    "boa-fe"
  ],
  "embaralhavel": true,
  "status": "validada",
  "validacao": {
    "por": "autor",
    "em": "2026-11-17",
    "obs": "Inédita para o Técnico Bancário; conferida pelo autor."
  },
  "versao": 1
});

