  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Ao contratar um empréstimo pessoal, o cliente adere a um seguro que, em caso de sua morte ou invalidez, quita ou amortiza o saldo devedor junto ao banco credor. Trata-se do seguro",
  "imagem": null,
  "alternativas": {
    "A": "de crédito à exportação.",
    "B": "de lucros cessantes.",
    "C": "prestamista.",
    "D": "garantia.",
    "E": "de responsabilidade civil geral."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** O **seguro prestamista** cobre o pagamento da dívida do segurado (total ou parcial) em eventos como morte e invalidez e, conforme o contrato, desemprego; o credor é o primeiro beneficiário. O **seguro garantia** assegura o cumprimento de obrigações contratuais de um tomador (por exemplo, a execução de uma obra). O de **responsabilidade civil** cobre danos que o segurado cause a terceiros. O de **crédito à exportação** protege o exportador contra o não pagamento do importador. **Lucros cessantes** cobre o lucro que uma empresa deixa de obter durante a paralisação após sinistro.\n\nRevisar: Apostila 03, §17.",
