  "gabarito": "B",
  "comentario": "**Gabarito: B.** A **RCF-V** cobre danos materiais e corporais que o segurado causar a **terceiros**. O **casco** protege o próprio veículo segurado (colisão, incêndio, roubo, conforme o contrato); a **cobertura compreensiva** é justamente o tipo mais amplo de cobertura de casco. A **APP** cobre morte ou invalidez dos **ocupantes** do veículo segurado. A **assistência 24 horas** é um serviço (guincho, chaveiro etc.), e não cobertura de danos a terceiros.\n\nRevisar: Apostila 03, §17.",
