  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Uma médica deseja proteger seu patrimônio contra indenizações que venha a ser condenada a pagar a pacientes por erros no exercício da profissão. O seguro indicado é o de",
  "imagem": null,
  "alternativas": {
    "A": "responsabilidade civil profissional.",
    "B": "acidentes pessoais.",
    "C": "vida em grupo.",
    "D": "seguro garantia.",
    "E": "lucros cessantes."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** O **seguro de responsabilidade civil** reembolsa as indenizações que o segurado deva pagar a terceiros por danos que lhes cause; na modalidade **profissional** (E&O), cobre erros e omissões no exercício da profissão. **Acidentes pessoais** e **vida em grupo** protegem a própria pessoa segurada, não terceiros prejudicados. O **seguro garantia** cobre o cumprimento de obrigações contratuais de um tomador perante um segurado. **Lucros cessantes** cobre perda de lucro de uma empresa paralisada por sinistro.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "seguros",
    "responsabilidade-civil"
  ],
  "embaralhavel": true,
  "status": "validada",
