BANCO.push({
  "id": "TB-CB-0016",
  "concursos": [
    "banestes-2026-tecnico-bancario"
  ],
  "banca_estilo": "FCC",
  "bloco": "especificos",
  "materia": "Conhecimentos Bancários e Securitários",
  "eixo": null,
  "topico": "Seguros pessoais e empresariais: modalidades",
  "ref_apostila": {
    "modulo": "03",
    "secao": "17",
    "titulo": "Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966",
    "link": "[[03 - Conhecimentos Bancários e Governança de TIC#17. Complementos FCC: seguros, previdência, capitalização, suitability, consumidor, compliance, ESG e Res. 4.966]]"
  },
  "origem": {
    "tipo": "simulado",
    "fonte": "Inédita Técnico Bancário (nov/2026)",
    "id_pai": null,
    "anulada": false
  },
  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Uma construtora vence uma licitação, e o órgão público contratante exige garantia de que a obra será executada conforme o contrato. A construtora contrata um seguro garantia. Nesse seguro, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "a seguradora indeniza a construtora se o órgão público atrasar os pagamentos da obra.",
    "B": "trata-se de um seguro de pessoas, pois garante a atividade dos empregados da construtora.",
    "C": "a construtora é a tomadora e o órgão público é o segurado, a ser indenizado se o contrato for descumprido.",
    "D": "a construtora é a segurada e o órgão público é o tomador, que paga o prêmio.",
    "E": "o órgão público é o estipulante e a construtora é a beneficiária da indenização."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** No **seguro garantia** há três partes: o **tomador** (quem deve cumprir a obrigação e contrata o seguro — a construtora), o **segurado** (o credor da obrigação — o órgão público) e a **seguradora**, que indeniza o segurado se o tomador descumprir o contrato. Inverter tomador e segurado está errado. Não há estipulante nem a construtora é beneficiária. O seguro garante a obrigação da construtora, e não os pagamentos do órgão público. É seguro de danos (patrimonial), e não de pessoas.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "seguros",
    "seguro-garantia"
  ],
  "embaralhavel": true,
  "status": "validada",
  "validacao": {
    "por": "autor",
    "em": "2026-11-17",
    "obs": "Inédita para o Técnico Bancário; conferida pelo autor."
  },
  "versao": 1
});

