  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Sobre o seguro rural, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "cobre apenas máquinas e equipamentos agrícolas, excluídas as lavouras e os animais.",
    "B": "é regulado e fiscalizado pela Comissão de Valores Mobiliários.",
    "C": "só pode ser contratado por cooperativas agropecuárias, nunca por produtores individuais.",
    "D": "não admite subvenção pública, por se tratar de seguro privado.",
    "E": "pode cobrir lavouras e rebanhos contra seca, geada e granizo, admitindo subvenção federal ao prêmio."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** O **seguro rural** reúne modalidades como agrícola, pecuário, de florestas e de benfeitorias e penhor rural, protegendo a produção contra riscos climáticos e outros. Existe o **Programa de Subvenção ao Prêmio do Seguro Rural (PSR)**, pelo qual o governo federal paga parte do prêmio. Não se restringe a máquinas: lavouras e rebanhos são o núcleo do seguro rural. Seguro é supervisionado pela **Susep**, e não pela CVM. Produtores individuais podem contratar. A subvenção existe justamente para baratear o seguro privado ao produtor.\n\nRevisar: Apostila 03, §17.",
