  "gabarito": "B",
  "comentario": "**Gabarito: B.** O **microsseguro** busca a **inclusão securitária** de quem tem baixa renda: produtos simples, baratos, de fácil compreensão e oferecidos por canais acessíveis (inclusive correspondentes e meios remotos). Não é voltado a grandes empresas. Continua sendo seguro e, portanto, sujeito à regulação do CNSP e à supervisão da **Susep**. Não se limita a riscos de engenharia. Exigir vistoria e perícia em toda contratação contraria a simplicidade que o define.\n\nRevisar: Apostila 03, §17.",
