  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Um participante optou pela tabela regressiva de Imposto de Renda em seu plano de previdência. Ao resgatar recursos aportados há 5 anos e meio, a alíquota de IR aplicável a esses recursos será de",
  "imagem": null,
  "alternativas": {
    "A": "30%.",
    "B": "25%.",
    "C": "20%.",
    "D": "15%.",
    "E": "35%."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** Na **tabela regressiva** da previdência complementar, a alíquota cai conforme o tempo de permanência de cada aporte: **35%** até 2 anos; **30%** de 2 a 4 anos; **25%** de 4 a 6 anos; **20%** de 6 a 8 anos; **15%** de 8 a 10 anos; e **10%** acima de 10 anos. Com 5 anos e meio, o aporte está na faixa de 4 a 6 anos: **25%**. 35% e 30% valem para prazos menores; 20% e 15%, para prazos maiores.\n\nRevisar: Apostila 03, §17.",
