  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre a tributação da previdência complementar aberta.\n\nI. Na tabela regressiva, a tributação é definitiva e a alíquota diminui conforme o prazo de permanência de cada contribuição no plano.\nII. Na tabela progressiva, há retenção na fonte e o imposto pode ser ajustado na declaração anual, conforme a renda total do contribuinte.\nIII. Desde a Lei nº 14.803/2024, o participante pode escolher o regime de tributação até o momento do primeiro resgate ou da obtenção do benefício.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "III, apenas.",
    "B": "I, apenas.",
    "C": "I e II, apenas.",
    "D": "I, II e III.",
    "E": "II e III, apenas."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** **I – correta.** A regressiva é exclusiva na fonte (definitiva), com alíquotas de 35% a 10% conforme o tempo de cada aporte. **II – correta.** Na progressiva, o IR retido é antecipação e entra no ajuste anual, segundo a tabela mensal/anual comum do IR. **III – correta.** A Lei 14.803/2024 permitiu adiar a escolha do regime para o momento do primeiro resgate ou da concessão do benefício (antes, a escolha era feita no ingresso no plano). Como as três estão corretas, as demais combinações estão erradas.\n\nRevisar: Apostila 03, §17.",
