  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Insatisfeito com as taxas de seu PGBL, um cliente quer transferir a reserva acumulada para um PGBL de outra entidade aberta. Sobre essa portabilidade, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "ela só pode ser feita na fase de benefício, após o início do recebimento da renda.",
    "B": "ela gera cobrança de IOF de 6% sobre o valor transferido.",
    "C": "os recursos passam diretamente entre as entidades, sem trânsito pela conta do cliente e sem IR.",
    "D": "o cliente deve primeiro resgatar o saldo, pagar o IR e depois aplicar o valor líquido no novo plano.",
    "E": "ela só é permitida para planos da mesma entidade, nunca para outra empresa."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** Na **portabilidade**, a reserva sai de um plano para outro **diretamente entre as entidades**, sem trânsito pela conta do participante; por não ser resgate, **não há IR** naquele momento, e o tempo de aplicação continua contando conforme as regras do regime escolhido. Resgatar e reaplicar seria um resgate tributado, e não portabilidade. É possível portar para outra entidade, não só dentro da mesma. A portabilidade é feita na fase de **acumulação**. Não há IOF de 6% nessa operação.\n\nRevisar: Apostila 03, §17.",
  "tags": [
    "tecnico-bancario",
    "previdencia",
    "portabilidade"
  ],
  "embaralhavel": true,
  "status": "validada",
