  "comentario": "**Gabarito: A.** **Carência** é o período em que o titular **não pode resgatar** o título. Além disso, o resgate antes do fim da vigência costuma devolver **menos** do que foi pago, pois parte das parcelas custeia sorteios e despesas (carregamento). Não há resgate integral e corrigido a qualquer tempo. A carência diz respeito ao resgate, e não ao primeiro sorteio. Resgatar não retira o direito de reclamar à Susep, supervisora do produto. Capitalização não tem cobertura do FGC.\n\nRevisar: Apostila 03, §17.",
