  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre a composição dos pagamentos de um título de capitalização.\n\nI. A cota de capitalização é a parte destinada a formar a provisão que garante o valor de resgate.\nII. A cota de sorteio é a parte destinada a custear os prêmios sorteados.\nIII. A cota de carregamento é a parte destinada a remunerar o titular com juros acima da poupança.\n\nEstá correto o que se afirma em",
