  "comentario": "**Gabarito: C.** O pagamento de um título divide-se em **cota de capitalização** (forma a provisão matemática para resgate), **cota de sorteio** (custeia os prêmios) e **cota de carregamento** (cobre despesas administrativas, de comercialização e o resultado da sociedade de capitalização). **I e II** estão corretas. **III** está errada: o carregamento cobre custos, e não remunera o titular; é justamente uma das razões pelas quais capitalização não é investimento.\n\nRevisar: Apostila 03, §17.",
