  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Uma consorciada não contemplada deixou de pagar as parcelas e foi excluída do grupo. Pela Lei nº 11.795/2008, a restituição dos valores que ela pagou ao fundo comum, observadas as deduções contratuais, ocorrerá",
  "imagem": null,
  "alternativas": {
    "A": "imediatamente, no dia útil seguinte ao pedido de exclusão, em valor integral corrigido.",
    "B": "somente se ela conseguir um novo consorciado para assumir a cota.",
    "C": "nunca, pois a desistência implica perda total dos valores pagos.",
    "D": "por meio de lance, que a excluída deve oferecer em assembleia.",
    "E": "quando sua cota for contemplada por sorteio, pois os excluídos concorrem aos sorteios para fins de restituição."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** Pela lei, o **consorciado excluído não contemplado** tem direito à restituição do que pagou ao fundo comum, e os excluídos **concorrem aos sorteios** para esse fim; contemplada a cota excluída, o valor é devolvido, com as deduções previstas (como multa contratual e taxa de administração). Não há devolução imediata e integral. Transferir a cota a terceiro é possível, mas não é condição para restituição. Perda total contrariaria a lei. O excluído não concorre por **lance**, apenas por sorteio.",
  "tags": [
    "tecnico-bancario",
    "consorcio",
    "exclusao"
  ],
