  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre o consórcio.\n\nI. O fundo comum é formado pelas parcelas dos consorciados e é utilizado para pagar os créditos dos contemplados.\nII. O fundo de reserva, quando previsto no contrato, serve para proteger o grupo em situações como a insuficiência de recursos do fundo comum.\nIII. A administradora deve pagar aos consorciados juros remuneratórios sobre as parcelas pagas, como ocorre em uma aplicação financeira.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "II, apenas.",
    "B": "I e II, apenas.",
    "C": "I e III, apenas.",
    "D": "I, II e III.",
    "E": "I, apenas."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** **I – correta.** O **fundo comum** é a principal parcela da prestação e serve para atribuir os créditos aos contemplados. **II – correta.** O **fundo de reserva**, se previsto, protege o grupo (por exemplo, cobrindo insuficiência do fundo comum em razão de inadimplência). **III – incorreta.** Consórcio não é aplicação financeira e não paga juros remuneratórios aos consorciados. Logo, apenas I e II.",
