  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "O modelo de negócios em que um banco utiliza sua rede de agências, canais digitais e base de clientes para distribuir seguros, planos de previdência e títulos de capitalização, geralmente de empresas do mesmo conglomerado, é conhecido como",
  "imagem": null,
  "alternativas": {
    "A": "securitização.",
    "B": "open finance.",
    "C": "resseguro.",
    "D": "bancassurance.",
    "E": "mutualismo."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** **Bancassurance** é a integração entre atividade bancária e securitária: o banco aproveita sua capilaridade e o relacionamento com clientes para vender produtos de seguradoras, EAPCs e sociedades de capitalização. **Open finance** é o compartilhamento padronizado de dados e serviços entre instituições, com consentimento do cliente. **Resseguro** é a transferência de riscos da seguradora a um ressegurador. **Mutualismo** é o princípio técnico do seguro. **Securitização** é a conversão de recebíveis em títulos negociáveis.\n\nRevisar: Apostila 03, §17.",
