  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Entre as vantagens do bancassurance para os bancos e para as seguradoras, destaca-se",
  "imagem": null,
  "alternativas": {
    "A": "a autorização para condicionar a abertura de conta à compra de um seguro.",
    "B": "a dispensa da análise de adequação do produto ao perfil do cliente.",
    "C": "a diversificação de receitas do banco e o acesso da seguradora a uma rede ampla e de baixo custo.",
    "D": "a eliminação da necessidade de supervisão da Susep sobre os seguros vendidos em agências.",
    "E": "a possibilidade de o banco assumir diretamente os riscos dos seguros em seu balanço, dispensando a seguradora."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** No **bancassurance**, o banco diversifica receitas (comissões e resultados do grupo) e aumenta a **fidelização**, e a seguradora ganha uma rede de distribuição **capilar** e com custo menor de aquisição de clientes. A Susep continua supervisionando os produtos, qualquer que seja o canal de venda. O risco segurado é assumido pela **seguradora**, e não pelo banco. Condicionar abertura de conta a seguro é venda casada. A adequação ao perfil do cliente continua exigível.\n\nRevisar: Apostila 03, §17.",
