  "texto_base": null,
  "enunciado": "Uma cliente teve negado o pagamento de uma indenização de seguro residencial e, sem solução na seguradora e na ouvidoria, quer apresentar reclamação ao órgão federal que supervisiona as seguradoras. Ela deve procurar a",
