  "gabarito": "B",
  "comentario": "**Gabarito: B.** A **Susep** é a autarquia que fiscaliza seguradoras, sociedades de capitalização, entidades abertas de previdência complementar e resseguradores, recebendo inclusive reclamações de consumidores. A **CVM** supervisiona o mercado de valores mobiliários. A **Previc** fiscaliza fundos de pensão (previdência fechada). A **ANS** regula planos e seguros de saúde, não o seguro residencial. O **CMN** é órgão normativo do sistema financeiro, e não atende reclamações.\n\nRevisar: Apostila 03, §4.",
