  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre os órgãos do Sistema Nacional de Seguros Privados e suas relações com o sistema financeiro.\n\nI. O Conselho Nacional de Seguros Privados (CNSP) é o órgão normativo que fixa as diretrizes e normas da política de seguros privados, capitalização e previdência complementar aberta.\nII. A Susep é autarquia que executa a política traçada pelo CNSP e fiscaliza as sociedades supervisionadas.\nIII. As regras para a aplicação dos recursos garantidores das provisões técnicas de seguradoras, sociedades de capitalização e entidades abertas de previdência são estabelecidas pelo Conselho Monetário Nacional.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "II, apenas.",
    "B": "I, apenas.",
    "C": "I e II, apenas.",
    "D": "I, II e III.",
    "E": "II e III, apenas."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** **I – correta.** O **CNSP** é o órgão **normativo** dos seguros privados, da capitalização, da previdência aberta e do resseguro. **II – correta.** A **Susep** é a autarquia **executora e fiscalizadora**. **III – correta.** Como os recursos das provisões técnicas são aplicados no mercado financeiro, as diretrizes dessas aplicações são fixadas pelo **CMN**. Assim, as três estão corretas.\n\nRevisar: Apostila 03, §2.",
