  "comentario": "**Gabarito: A.** Fundo de pensão é **entidade fechada** de previdência complementar (EFPC): o órgão normativo é o **CNPC** e a supervisão é da **Previc**. **CNSP/Susep** cuidam da previdência **aberta**, de seguros e da capitalização. **CMN/BC** cuidam das instituições financeiras e de pagamento. A combinação CNPC e Susep mistura os dois subsistemas. **CMN/CVM** remete ao mercado de valores mobiliários.\n\nRevisar: Apostila 03, §2.",
