  "comentario": "**Gabarito: B.** No Sistema Nacional de Seguros Privados, o **CNSP** é o órgão **normativo** (colegiado) e a **Susep** é a **autarquia** executora e **fiscalizadora**. A primeira errada inverte os papéis. A Susep tem personalidade jurídica própria e é vinculada ao Ministério da Fazenda, e não é departamento do BC. A meta da Selic é definida pelo **Copom**. Consórcios e instituições de pagamento são supervisionados pelo **Banco Central**.\n\nRevisar: Apostila 03, §2.",
