  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Pelas normas do CMN sobre tarifas, a pessoa física titular de conta de depósitos à vista tem direito a um conjunto de serviços essenciais gratuitos. Entre eles, inclui-se",
  "imagem": null,
  "alternativas": {
    "A": "o fornecimento de cartão de débito e a realização de até quatro saques por mês.",
    "B": "a emissão ilimitada de talões de cheque, independentemente do perfil do cliente.",
    "C": "a concessão gratuita de limite de cheque especial e de cartão de crédito.",
    "D": "um número ilimitado de saques e transferências mensais em qualquer canal.",
    "E": "a isenção de juros nas operações de crédito pessoal contratadas na conta."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** Os **serviços essenciais** gratuitos da conta corrente de pessoa física incluem, entre outros, o fornecimento de **cartão de débito**, até **quatro saques** por mês, transferências entre contas na própria instituição em quantidade limitada, extratos mensais em número limitado e consultas pela internet; o fornecimento de folhas de cheque também é limitado e condicionado ao cliente reunir os requisitos para usar cheques. Talões ilimitados não estão entre os serviços gratuitos. Cheque especial e cartão de crédito são produtos de crédito, sujeitos a análise e encargos. Saques e transferências gratuitos são em número limitado. Isenção de tarifa não significa isenção de juros.\n\nRevisar: Apostila 03, §6.",
