  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Sobre o cheque especial, é correto afirmar que se trata de",
  "imagem": null,
  "alternativas": {
    "A": "um financiamento de longo prazo vinculado à aquisição de um bem, que fica alienado ao banco.",
    "B": "uma linha de crédito que cobra juros sobre todo o limite disponível, mesmo que não utilizado.",
    "C": "limite rotativo pré-aprovado na conta, com juros sobre o valor e o período efetivamente utilizados.",
    "D": "um empréstimo com parcelas fixas descontadas diretamente da folha de pagamento do cliente.",
    "E": "uma modalidade de cheque garantido pelo FGC, sem cobrança de juros."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** O **cheque especial** é crédito **rotativo** pré-aprovado: o cliente usa quando o saldo fica negativo e paga juros sobre o valor e os dias de utilização. Como é uma das linhas mais caras, deve ser usado só em emergências e por pouco tempo. Desconto em folha caracteriza o **consignado**. Não há relação com o FGC e há, sim, cobrança de juros. Financiamento de bem com alienação fiduciária é o **CDC** ou financiamento de veículos. Os juros incidem sobre o valor utilizado, e não sobre o limite total disponível.\n\nRevisar: Apostila 03, §6.",
