  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre o crédito rotativo do cartão de crédito.\n\nI. Ao pagar valor inferior ao total da fatura, o saldo restante passa a ser financiado no crédito rotativo, sujeito a juros.\nII. O saldo financiado no rotativo não pode permanecer nessa modalidade indefinidamente, devendo a instituição oferecer ao cliente opção de parcelamento em condições mais vantajosas.\nIII. Desde 2024, os juros e encargos do rotativo e do parcelamento da fatura não podem ultrapassar o valor original da dívida.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I, apenas.",
    "B": "I e II, apenas.",
    "C": "I e III, apenas.",
    "D": "II e III, apenas.",
    "E": "I, II e III."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** **I – correta.** O pagamento parcial da fatura (acima do mínimo) leva o saldo para o **rotativo**. **II – correta.** Pelas normas do CMN, o saldo só pode ficar no rotativo até o vencimento da fatura seguinte; depois, a instituição deve oferecer **parcelamento** em condições mais vantajosas. **III – correta.** A Lei 14.690/2023 limitou, a partir de janeiro de 2024, o total de juros e encargos do rotativo e do parcelamento da fatura a **100% do valor original** da dívida. Por isso, todas estão corretas.\n\nRevisar: Apostila 03, §6.",
