  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "O crédito consignado costuma ter taxas de juros menores que as do crédito pessoal sem garantia porque",
  "imagem": null,
  "alternativas": {
    "A": "o tomador oferece um imóvel em hipoteca como garantia.",
    "B": "as parcelas são descontadas na folha ou no benefício, o que reduz o risco de inadimplência.",
    "C": "o FGC garante o pagamento das parcelas em caso de desemprego do tomador.",
    "D": "não há limite para o comprometimento da renda do tomador.",
    "E": "o Banco Central subsidia integralmente os juros dessas operações de crédito."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** No **consignado**, a parcela é **descontada na fonte** (salário, aposentadoria ou pensão), dentro de uma **margem consignável**, o que reduz muito o risco de crédito e permite juros menores. O BC não subsidia os juros. Não há hipoteca; o desconto em folha é a principal proteção do credor. O FGC protege depositantes e investidores em certos produtos, e não paga dívidas de tomadores. Existe limite de comprometimento da renda (a margem consignável).\n\nRevisar: Apostila 03, §6.",
