  "enunciado": "Um produtor rural procura a agência para financiar a compra de um trator, que será usado por vários anos na propriedade. No crédito rural, essa operação enquadra-se na finalidade de",
  "imagem": null,
  "alternativas": {
    "A": "capital de giro de pessoa física.",
    "B": "custeio.",
    "C": "comercialização.",
    "D": "investimento.",
    "E": "industrialização."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** As finalidades do **crédito rural** são **custeio** (despesas normais de um ciclo produtivo, como sementes, adubos e defensivos), **investimento** (bens e serviços cujo uso se estende por vários ciclos, como máquinas, tratores e benfeitorias), **comercialização** (recursos para a fase de venda da produção) e **industrialização** (beneficiamento ou transformação da produção). O trator é bem durável: **investimento**. Custeio cobre insumos de um ciclo; comercialização e industrialização referem-se a fases posteriores à produção. “Capital de giro de pessoa física” não é finalidade do crédito rural.\n\nRevisar: Apostila 03, §6.",
  "tags": [
    "tecnico-bancario",
    "produtos",
    "credito-rural"
  ],
  "embaralhavel": true,
  "status": "validada",
