  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Antes de contratar um crédito direto ao consumidor (CDC) para comprar um automóvel, o cliente deve ser informado do Custo Efetivo Total (CET) da operação. O CET",
  "imagem": null,
  "alternativas": {
    "A": "só precisa ser informado após a assinatura do contrato, junto com o carnê.",
    "B": "indica a rentabilidade que o cliente obteria se aplicasse o valor em CDB.",
    "C": "expressa em taxa o custo total do crédito, incluindo juros, tarifas, tributos e seguros.",
    "D": "corresponde apenas à taxa de juros nominal do contrato, sem tarifas ou tributos.",
    "E": "é o valor da parcela mensal, que deve ser igual em todos os bancos."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** O **CET** é a taxa que reúne **todos os encargos e despesas** da operação de crédito (juros, tarifas, IOF, seguros, registros etc.) e deve ser informado **antes da contratação**, permitindo ao cliente comparar ofertas de diferentes instituições. Não se limita à taxa de juros. Não é o valor da parcela, nem é uniforme entre bancos. Informá-lo só depois da assinatura frustraria sua finalidade comparativa. O CET mede custo de crédito, e não rentabilidade de aplicação.\n\nRevisar: Apostila 03, §6.",
