  "gabarito": "B",
  "comentario": "**Gabarito: B.** **CDB** (Certificado de Depósito Bancário) e **RDB** (Recibo de Depósito Bancário) são **depósitos a prazo**. A diferença clássica é que o **CDB é transferível** (pode ser negociado antes do vencimento) e o **RDB não**. Ambos têm cobertura do **FGC**. A primeira errada inverte a característica. Ambos têm FGC. São emitidos por bancos, e não pelo Tesouro. São de **renda fixa** (pré ou pós-fixada), e não variável.\n\nRevisar: Apostila 03, §6.",
