  "gabarito": "D",
  "comentario": "**Gabarito: D.** **LCI** e **LCA** são títulos emitidos por instituições financeiras, **lastreados** em operações de crédito imobiliário e do agronegócio, respectivamente, e estão entre os produtos cobertos pelo **FGC**. Não são títulos públicos. São títulos de renda fixa, e não ações. O lastro não exclui a cobertura do FGC. Há prazos mínimos de carência fixados pelo CMN, diferentemente da poupança, que tem liquidez diária.\n\nRevisar: Apostila 03, §6.",
