  "gabarito": "E",
  "comentario": "**Gabarito: E.** **Debênture** é **título de dívida** emitido por sociedade anônima: quem compra **empresta** à empresa e recebe juros e principal conforme a **escritura de emissão**. Sócio com direito a voto é o titular de **ações ordinárias**. Debênture não é cota de fundo. Debêntures **não** têm cobertura do FGC; o risco é o da empresa emissora. Título público federal é emitido pelo Tesouro Nacional.\n\nRevisar: Apostila 03, §6.",
