  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Sobre o Tesouro Direto, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "negocia ações de empresas estatais federais em bolsa.",
    "B": "oferece títulos públicos federais a pessoas físicas pela internet, com risco do Tesouro Nacional.",
    "C": "só admite títulos prefixados, sem opções atreladas à Selic ou à inflação.",
    "D": "é restrito a investidores qualificados, com aplicação mínima de R$ 1 milhão.",
    "E": "é um fundo de investimento administrado pelo Banco Central, garantido pelo FGC."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** O **Tesouro Direto** permite a pessoas físicas comprar **títulos públicos federais** (Tesouro Selic, Prefixado, IPCA+ etc.) pela internet, por meio de instituições habilitadas, com **custódia na B3**. O risco é o do **Tesouro Nacional** (risco soberano). Não é fundo nem tem FGC. Não negocia ações. Há títulos **pós-fixados** (Selic) e **híbridos** (IPCA+), além dos prefixados. É acessível ao público em geral, com valores mínimos baixos.\n\nRevisar: Apostila 03, §6.",
