  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Uma empresa faz sua oferta pública inicial de ações (IPO) e, meses depois, essas ações passam a ser negociadas diariamente na bolsa entre investidores. Essas duas situações ocorrem, respectivamente, no",
