  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Se o Banco Central eleva a alíquota do recolhimento compulsório sobre depósitos, o efeito esperado é",
  "imagem": null,
  "alternativas": {
    "A": "a redução dos recursos disponíveis para empréstimos, contraindo o crédito.",
    "B": "o aumento dos recursos livres dos bancos, expandindo o crédito.",
    "C": "a redução imediata da meta da taxa Selic.",
    "D": "a elevação dos gastos públicos, por se tratar de instrumento de política fiscal.",
    "E": "a garantia automática de todos os depósitos pelo FGC."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** O **compulsório** é a parcela dos depósitos que os bancos devem manter no Banco Central. Elevá-lo **retira recursos** que poderiam ser emprestados: é medida **contracionista** de política monetária. O efeito é o inverso de expandir o crédito. A meta Selic é decidida pelo **Copom** e não muda automaticamente com o compulsório. Compulsório é instrumento de política **monetária**, e não fiscal. Não tem relação com a garantia do FGC.\n\nRevisar: Apostila 03, §3.",
