  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Um cliente pergunta a diferença entre fundo de investimento aberto e fechado. A resposta correta é que",
  "imagem": null,
  "alternativas": {
    "A": "fundos abertos são garantidos pelo FGC e fundos fechados não.",
    "B": "fundos fechados não são regulados pela CVM.",
    "C": "no aberto, o cotista pode pedir resgate; no fechado, sai em regra vendendo as cotas no mercado secundário.",
    "D": "no fechado, o resgate é diário; no aberto, só ocorre ao final do prazo de duração do fundo.",
    "E": "o fundo fechado não pode ser negociado em bolsa, enquanto o aberto é negociado na B3."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** No **fundo aberto**, as cotas podem ser emitidas e **resgatadas** conforme o regulamento. No **fundo fechado**, as cotas só são resgatadas ao fim do prazo (ou em situações previstas), e o investidor que quer sair antes **vende suas cotas** a outro investidor, muitas vezes em bolsa (como ocorre com muitos fundos imobiliários). A primeira errada inverte as características. É o fundo fechado que costuma ter cotas negociadas em bolsa. **Nenhum** fundo tem garantia do FGC. Ambos são regulados e supervisionados pela **CVM**.\n\nRevisar: Apostila 03, §6.",
