  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Um cliente tem um empréstimo pessoal em um banco e recebeu de outra instituição proposta de juros menores para a mesma dívida. Ao usar a portabilidade de crédito,",
  "imagem": null,
  "alternativas": {
    "A": "o cliente precisa quitar a dívida com recursos próprios antes de contratar na nova instituição.",
    "B": "a instituição original pode cobrar tarifa de transferência de até 10% do saldo devedor.",
    "C": "a portabilidade só é permitida para financiamentos imobiliários.",
    "D": "a nova instituição empresta um valor maior que o saldo devedor, liberando a diferença ao cliente.",
    "E": "a nova instituição quita a dívida na original e o cliente passa a dever a ela, sem tarifa de portabilidade."
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** Na **portabilidade de crédito**, a instituição proponente transfere os recursos diretamente à credora original, quitando a operação, e o cliente passa a ter a dívida com a nova instituição. A operação **não pode ter tarifa** cobrada do cliente pela portabilidade. O cliente não precisa ter os recursos para quitar antes. Não existe tarifa de 10%. A portabilidade vale para diversas modalidades (pessoal, consignado, veículos, imobiliário), e não só para o imobiliário. A nova operação não pode ter valor superior ao saldo devedor; liberar dinheiro novo seria refinanciamento, e não portabilidade.\n\nRevisar: Apostila 03, §6.",
