  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Uma cliente possui um PGBL e um VGBL em uma entidade aberta de previdência e deseja transferir as reservas para outra entidade. Sobre essa portabilidade, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "a reserva de PGBL vai para outro PGBL e a de VGBL para outro VGBL, sem mistura entre os dois tipos.",
    "B": "ela pode reunir as duas reservas em um único VGBL, pois ambos são planos de previdência.",
    "C": "a portabilidade só é possível depois do início do recebimento da renda.",
    "D": "a portabilidade entre entidades distintas é proibida, sendo permitida apenas a troca de fundo na mesma entidade.",
    "E": "a portabilidade exige o resgate e o pagamento do IR antes da transferência."
  },
  "gabarito": "A",
  "comentario": "**Gabarito: A.** Na previdência aberta, a portabilidade ocorre **entre planos da mesma natureza** (PGBL para PGBL; VGBL para VGBL). Como o PGBL tem contribuições deduzidas e tributação sobre o total, e o VGBL tributa só os rendimentos, **não se misturam** as reservas. Por isso, não é possível juntar tudo em um VGBL. A portabilidade é feita na **fase de acumulação**. É permitida para outra entidade. Não há resgate nem IR na portabilidade.\n\nRevisar: Apostila 03, §17.",
