  "comentario": "**Gabarito: C.** Na **portabilidade de crédito**, a liquidação da operação original se dá por **transferência direta** entre as instituições (uma TED específica para portabilidade), **sem passar pela conta do cliente**. Isso evita desvio de finalidade e garante que a dívida original seja efetivamente quitada. Depósito na conta do cliente, entrega em espécie, boleto do cliente ou cheque nominal a ele fariam os recursos transitarem pelo cliente, o que descaracterizaria a portabilidade.\n\nRevisar: Apostila 03, §6.",
