  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Um banco concede hoje um empréstimo a um cliente com excelente histórico, sem nenhum atraso. Sob a Resolução CMN nº 4.966/2021, em relação à provisão para perdas, é correto afirmar que o banco",
