  "gabarito": "D",
  "comentario": "**Gabarito: D.** Na **alienação fiduciária**, o devedor transfere ao credor a **propriedade resolúvel** do bem, mantendo a **posse direta**; quitada a dívida, a propriedade volta plena ao devedor. É a garantia típica de veículos e de muitos financiamentos imobiliários. A **hipoteca** recai sobre imóveis (e alguns bens, como navios e aeronaves), sem transferir a propriedade. A **fiança** é garantia pessoal. No **penhor comum**, o bem móvel é, em regra, entregue ao credor. Na **anticrese**, o credor recebe os frutos de um imóvel para se pagar.",
