  "gabarito": "E",
  "comentario": "**Gabarito: E.** A **Súmula 297 do STJ** estabelece que “o Código de Defesa do Consumidor é aplicável às instituições financeiras”; o STF também reconheceu essa aplicação. Não há restrição às cooperativas nem só a tarifas. As normas do CMN e do BC convivem com o CDC, sem excluí-lo. Bancos públicos e privados estão igualmente sujeitos ao CDC.\n\nRevisar: Apostila 03, §17.",
