  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Um consumidor superendividado pede a repactuação de suas dívidas em processo conciliatório com os credores, nos termos da Lei nº 14.181/2021. Entre as dívidas abaixo, pode ser incluída na repactuação a dívida decorrente de",
  "imagem": null,
  "alternativas": {
    "A": "contratação feita dolosamente, sem o propósito de pagar.",
    "B": "financiamento imobiliário.",
    "C": "crédito rural.",
    "D": "fatura de cartão de crédito e empréstimo pessoal sem garantia.",
    "E": "contrato de crédito com garantia real."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** A repactuação abrange **dívidas de consumo**, como cartão de crédito, empréstimo pessoal, crediário e contas de consumo. A lei **exclui** do processo de repactuação as dívidas oriundas de contratos com **garantia real**, de **financiamentos imobiliários** e de **crédito rural**, além das contraídas **dolosamente** sem o propósito de pagamento (sem boa-fé). Por isso, as quatro alternativas erradas trazem justamente hipóteses excluídas.\n\nRevisar: Apostila 03, §17.",
