  "enunciado": "Uma técnica bancária organiza seus e-mails no Gmail e quer que a mesma mensagem de um cliente apareça tanto no grupo “Crédito” quanto no grupo “Pendências”, sem duplicar a mensagem. No Gmail, isso é possível porque",
