  "comentario": "**Gabarito: B.** O **modo confidencial** remove do destinatário as opções de encaminhar, copiar, imprimir e baixar, permite definir expiração, revogar o acesso e exigir senha por SMS (enviada ao **destinatário**). O próprio Google alerta que ele **não impede** capturas de tela ou fotos, por isso não dispensa o juízo sobre o que pode ser enviado. Não é criptografia de ponta a ponta com chave privada do remetente, e a expiração bloqueia o acesso à mensagem, mas não alcança cópias feitas por fora.",
