  "enunciado": "Em uma planilha do Google Sheets, a coluna B (B2 a B5) traz o volume de vendas de quatro empregados: 6500, 4800, 5000 e 7200. Em C2 foi digitada a fórmula abaixo, depois copiada para C3, C4 e C5:\n\n`=SE(B2>=5000;B2*2%;0)`\n\nA soma dos valores exibidos em C2:C5 é",
  "imagem": null,
