  "enunciado": "Vários empregados trabalham ao mesmo tempo em uma planilha do Google Sheets com a carteira de clientes. Um deles quer filtrar apenas os clientes da sua agência para analisá-los, sem alterar o que os demais estão vendo na tela. O recurso indicado é",
