  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Considere os usos do Gemini no Google Workspace.\n\nI. No Google Slides, gerar imagens ou um rascunho de apresentação a partir de uma descrição em linguagem natural.\nII. No Google Docs, pedir uma primeira versão de um texto ou a reescrita de um parágrafo em tom mais formal.\nIII. No Google Sheets, pedir ajuda para organizar dados ou montar fórmulas descrevendo o que se deseja.\n\nSão usos compatíveis com os recursos de IA do Workspace os indicados em",
