  "comentario": "**Gabarito: E.** As três situações correspondem a recursos de IA integrados ao Workspace: no **Slides**, criar imagens e rascunhos de slides a partir de instruções; no **Docs**, gerar e reescrever textos (ajustando tom, tamanho, formalidade); no **Sheets**, ajudar a organizar dados, criar tabelas e sugerir fórmulas. Por isso, qualquer alternativa que exclua uma delas está incompleta. Em todos os casos, o resultado deve ser revisado por quem o utiliza.",
