  "enunciado": "Um sistema de prevenção à fraude com IA analisa em tempo real as transações de cartão e bloqueia preventivamente uma compra legítima de um cliente que estava viajando. Esse caso é um",
  "imagem": null,
  "alternativas": {
    "A": "caso de viés algorítmico, que obriga o banco a desligar o sistema.",
    "B": "falso negativo, porque o sistema deixou de detectar uma fraude.",
    "C": "verdadeiro positivo, porque toda compra fora do padrão é fraude.",
    "D": "falso positivo, que gera atrito com o cliente e precisa ser equilibrado com a capacidade de detectar fraudes reais.",
    "E": "verdadeiro negativo, porque a transação foi corretamente aprovada."
  },
  "gabarito": "D",
  "comentario": "**Gabarito: D.** **Falso positivo** é o alarme indevido: o modelo apontou fraude (positivo) em uma transação legítima. **Falso negativo** seria deixar passar uma fraude real. **Verdadeiro positivo** seria bloquear uma fraude de fato; e **verdadeiro negativo**, aprovar uma compra legítima — o oposto do que ocorreu. Um bloqueio isolado não caracteriza **viés** (tratamento sistematicamente desfavorável a um grupo), e a resposta adequada é calibrar o modelo e oferecer canais de confirmação ágeis, não desligá-lo.",
  "tags": [
    "tecnico-bancario",
    "ia",
    "fraude"
  ],
  "embaralhavel": true,
  "status": "validada",
