  "texto_base": null,
  "enunciado": "Uma técnica digitava uma proposta em um editor de textos quando faltou energia, e o computador desligou. Ao religá-lo, ela percebeu que perdeu o que não havia salvo, mas os arquivos gravados antes continuavam no SSD. Isso ocorre porque",
