  "gabarito": "A",
  "comentario": "**Gabarito: A.** O **SSD** armazena dados em **memória flash** (estado sólido), sem discos girando nem cabeça de leitura, por isso é mais rápido, silencioso e resistente a impactos que o **HD**, que usa pratos magnéticos giratórios. O SSD é **não volátil** e não substitui a RAM; é mais rápido (e, em geral, ainda com custo por gigabyte maior que o do HD); e existe em versões internas (SATA, NVMe) e externas.",
