  "enunciado": "No Windows 11, associe as teclas de atalho às ações.\n\n1. Tecla do Windows + L\n2. Tecla do Windows + E\n3. Ctrl + Shift + Esc\n4. Alt + Tab\n\n( ) Abrir o Explorador de Arquivos.\n( ) Bloquear o computador.\n( ) Alternar entre as janelas abertas.\n( ) Abrir o Gerenciador de Tarefas.\n\nA sequência correta, de cima para baixo, é",
