  "comentario": "**Gabarito: B.** **Win + E** abre o Explorador de Arquivos (2); **Win + L** bloqueia a sessão, exigindo senha, PIN ou biometria para voltar (1); **Alt + Tab** alterna entre as janelas (4); e **Ctrl + Shift + Esc** abre direto o Gerenciador de Tarefas (3). Logo, 2, 1, 4, 3. As demais sequências trocam pelo menos dois desses pares — por exemplo, Win + L com Win + E, ou Alt + Tab com o Gerenciador de Tarefas.",
