  "formato": "multipla_5",
  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre o Linux.\n\nI. Linux é, em sentido estrito, o núcleo (kernel) do sistema; Ubuntu, Debian e Fedora são distribuições que reúnem esse núcleo a outros programas.\nII. Cada arquivo tem permissões de leitura (r), escrita (w) e execução (x), definidas separadamente para o dono, o grupo e os demais usuários.\nIII. Por ser software livre, o Linux não possui controle de usuários nem senhas.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "I, II e III.",
    "B": "II e III, apenas.",
    "C": "I e II, apenas.",
    "D": "I, apenas.",
    "E": "II, apenas."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** **I** é correta: o Linux é o kernel, e as **distribuições** empacotam o núcleo com utilitários, interface e gerenciador de pacotes. **II** é correta: o modelo de permissões r, w e x vale para **dono, grupo e outros** (alterado, por exemplo, com chmod). **III** é falsa: o Linux é multiusuário, com contas, senhas e o superusuário (root); ser livre não tem relação com ausência de controle de acesso. Por isso só “I e II, apenas” está correta.",
  "tags": [
    "tecnico-bancario",
    "linux"
  ],
  "embaralhavel": true,
  "status": "validada",
