  "comentario": "**Gabarito: C.** As **aspas** buscam a expressão exata; **site:** restringe a um domínio; **filetype:** (ou ext:) restringe o tipo de arquivo; e o **sinal de menos** colado à palavra a exclui dos resultados. Sem aspas, os termos podem aparecer separados, e “+concurso” ou “\"concurso\"” exigiriam a palavra em vez de excluí-la; trocar os valores de site: e filetype: inverte os operadores; e “OR” aceitaria páginas com só uma das palavras, enquanto “pdf” solto é apenas mais um termo de busca.",
