  "gabarito": "E",
  "comentario": "**Gabarito: E.** **Phishing** é a mensagem fraudulenta que se passa por instituição confiável, explorando urgência ou medo para obter senhas, dados ou cliques. Os sinais clássicos estão todos ali: ameaça de bloqueio, prazo curto, pedido de dados e link para domínio diferente do oficial. Logotipo é facilmente copiado e não prova legitimidade; **ransomware** é malware que cifra arquivos e pede resgate; **cookie** é dado de navegação; e backup não chega por e-mail com ameaças.",
