  "gabarito": "A",
  "comentario": "**Gabarito: A.** **Ransomware** sequestra dados (cifrando-os ou ameaçando divulgá-los) e cobra resgate. A defesa inclui backups **isolados** (offline ou imutáveis) e testados, atualizações e controle de acesso, além do tratamento do incidente pelos canais devidos. **Spyware** espiona, não cifra. Pagar não garante a recuperação nem encerra obrigações de resposta e comunicação; reiniciar não desfaz a criptografia; e backups acessíveis na mesma rede costumam ser cifrados junto.",
