  "comentario": "**Gabarito: C.** No golpe do **QR code falso**, um adesivo substitui o código legítimo, desviando o pagamento ou levando a sites maliciosos. A proteção é verificar, **antes de confirmar**, os dados que o aplicativo mostra (recebedor, instituição, valor). Códigos impressos são facilmente substituídos; abrir links desconhecidos é arriscado; o Pix não é “desfeito livremente” (há mecanismos como o MED, sujeitos a análise e sem garantia de devolução); e ler duas vezes o mesmo código falso não muda o recebedor.",
