  "texto_base": null,
  "enunciado": "Sobre a engenharia social, considere as afirmativas.\n\nI. Explora características humanas, como confiança, medo, pressa e respeito à autoridade, para obter informações ou acessos.\nII. Pode ocorrer sem uso de tecnologia, como quando alguém entra em área restrita “aproveitando a porta” aberta por um empregado.\nIII. Por depender do fator humano, é combatida principalmente com conscientização, treinamento e procedimentos de verificação.\n\nEstá correto o que se afirma em",
