  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "A autenticação multifator (MFA) combina fatores de categorias diferentes: algo que o usuário **sabe**, algo que ele **tem** e algo que ele **é**. É exemplo de autenticação multifator",
