  "comentario": "**Gabarito: B.** A **MFA** exige fatores de **categorias distintas**. Senha (algo que se sabe) + código do autenticador no celular (algo que se tem) formam dois fatores. Senha + pergunta secreta, duas senhas ou PIN repetido são todos “algo que se sabe”: várias etapas, mas um só fator. A senha salva no navegador continua sendo um único fator (e ainda fica exposta a quem usar o computador).",
