  "comentario": "**Gabarito: D.** **Gerenciadores de senhas** guardam senhas longas, aleatórias e **únicas** em cofre cifrado, liberado por uma senha mestra (idealmente com MFA). Reaproveitar a mesma senha, com pequenas variações, deixa todos os sistemas expostos quando uma vaza; papel no monitor é visível para qualquer pessoa no ambiente; datas de nascimento são facilmente descobertas; e senhas são pessoais e intransferíveis — compartilhá-las impede saber quem fez cada operação.",
