  "enunciado": "Na análise de uma proposta de financiamento, o banco consulta e trata dados cadastrais e de histórico de pagamentos do cliente para avaliar o risco de crédito. Entre as hipóteses de tratamento previstas na LGPD, a que fundamenta especificamente esse tipo de tratamento é",
