  "dificuldade": 3,
  "texto_base": null,
  "enunciado": "Considere as afirmativas sobre a aplicação da LGPD em um banco.\n\nI. O titular pode pedir informação sobre as entidades públicas e privadas com as quais o banco compartilhou seus dados.\nII. Biometria facial coletada para autenticação no aplicativo é dado pessoal sensível, e seu tratamento para prevenção à fraude e segurança do titular encontra amparo na lei.\nIII. Por estar sujeito a sigilo bancário, o banco fica dispensado de cumprir a LGPD.\n\nEstá correto o que se afirma em",
  "imagem": null,
  "alternativas": {
    "A": "II, apenas.",
    "B": "I e II, apenas.",
    "C": "I, II e III.",
    "D": "II e III, apenas.",
    "E": "I, apenas."
  },
  "gabarito": "B",
  "comentario": "**Gabarito: B.** **I** é correta: entre os direitos do titular está a informação sobre as entidades com as quais o controlador realizou **uso compartilhado** de dados. **II** é correta: dado **biométrico** é sensível, e a LGPD admite seu tratamento para **garantia da prevenção à fraude e à segurança do titular** em processos de identificação e autenticação. **III** é falsa: o sigilo bancário (LC 105/2001) convive com a LGPD; ele reforça a proteção, mas não dispensa o banco de cumprir a lei. Por isso a resposta é “I e II, apenas”.",
  "tags": [
    "tecnico-bancario",
    "lgpd"
  ],
