  "formato": "multipla_5",
  "dificuldade": 1,
  "texto_base": null,
  "enunciado": "Para estimar a renda média dos 80.000 correntistas de um banco, um analista sorteou 400 deles e calculou a renda média desses 400 clientes. Nessa situação, é correto afirmar que",
  "imagem": null,
  "alternativas": {
    "A": "como só 400 clientes foram pesquisados, o estudo é um censo.",
    "B": "a amostra só seria válida se incluísse pelo menos metade da população.",
    "C": "os 80.000 correntistas formam a população, os 400 sorteados formam a amostra, e a média dos 400 é uma estatística usada para estimar o parâmetro (a média dos 80.000).",
    "D": "os 400 sorteados formam a população, pois são os clientes efetivamente pesquisados.",
    "E": "a média dos 400 clientes é o parâmetro, e a média dos 80.000 é a estatística."
  },
  "gabarito": "C",
  "comentario": "**Gabarito: C.** **População** é o conjunto completo de interesse (80.000 correntistas); **amostra** é a parte observada (400). **Parâmetro** é a medida da população (a renda média real dos 80.000, desconhecida); **estatística** é a medida calculada na amostra, usada como estimativa. Inverter população/amostra ou parâmetro/estatística está errado; **censo** é a pesquisa de toda a população; e a validade de uma amostra depende de como ela é selecionada (aleatoriedade) e do seu tamanho absoluto, não de cobrir metade da população.",
  "tags": [
    "tecnico-bancario",
    "amostragem"
  ],
