  "formato": "multipla_5",
  "dificuldade": 2,
  "texto_base": null,
  "enunciado": "Um auditor precisa selecionar 100 contratos de um total de 2.000, numerados de 1 a 2.000, usando amostragem **sistemática**. Ele sorteou o número 7 como ponto de partida entre os primeiros contratos do intervalo. O 5º contrato selecionado será o de número",
  "imagem": null,
  "alternativas": {
    "A": "107",
    "B": "35",
    "C": "27",
    "D": "67",
    "E": "87"
  },
  "gabarito": "E",
  "comentario": "**Gabarito: E.** Na amostragem **sistemática**, o intervalo é k = N ÷ n = 2.000 ÷ 100 = **20**, e os selecionados são 7, 27, 47, 67, **87**, ... (7 + 4 × 20 = 87). 107 seria o 6º; 67, o 4º; 27, o 2º; e 35 resultaria de usar intervalo 7 (somar o ponto de partida repetidamente), confundindo-o com k.",
