  "enunciado": "Um banco tem 12.000 clientes: 7.200 do varejo, 3.600 de alta renda e 1.200 empresas. Em uma pesquisa de satisfação com amostragem **estratificada proporcional** de 300 clientes, o número de clientes de alta renda na amostra deve ser",
