  "enunciado": "Em uma pequena empresa cliente do banco, os salários mensais dos seis empregados, em R$ mil, são: 3, 3, 4, 4, 5 e 29 (este último, o do sócio-administrador). Para representar o salário típico desses empregados, é mais adequado usar",
