  "comentario": "**Gabarito: B.** Média = (3 + 3 + 4 + 4 + 5 + 29) ÷ 6 = 48 ÷ 6 = **R$ 8 mil**, maior do que o salário de cinco dos seis empregados: a média é sensível a **valores extremos (outliers)**. A **mediana**, (4 + 4) ÷ 2 = **R$ 4 mil**, é robusta a eles. A média não é sempre a melhor medida; a mediana não é a média entre o mínimo e o máximo (isso daria 16); descartar o valor extremo não muda o fato de que a média do conjunto é 8; e a moda é o valor mais frequente (aqui há duas, 3 e 4), não o maior.",
