  "enunciado": "Considere as afirmativas sobre medidas de dispersão de um conjunto de saldos em reais.\n\nI. A variância é expressa em reais ao quadrado, enquanto o desvio padrão é expresso em reais, a mesma unidade dos dados.\nII. Se todos os saldos forem iguais, o desvio padrão será zero.\nIII. A amplitude considera todos os valores do conjunto e, por isso, não é afetada por valores extremos.\n\nEstá correto o que se afirma em",
