  "enunciado": "Em um grupo de 100 clientes, 60 têm cartão de crédito, 45 têm seguro e 25 têm os dois produtos. Escolhendo-se um cliente ao acaso, a probabilidade de que ele tenha **cartão ou seguro** é",
