  "enunciado": "Considere as afirmativas sobre conceitos de probabilidade.\n\nI. Dois eventos são mutuamente exclusivos quando não podem ocorrer simultaneamente; nesse caso, a probabilidade de sua interseção é zero.\nII. A soma da probabilidade de um evento com a probabilidade de seu complementar é igual a 1.\nIII. A probabilidade de um evento muito provável pode ser maior que 1.\n\nEstá correto o que se afirma em",
