  "comentario": "**Gabarito: E.** **I** é correta: eventos **mutuamente exclusivos** (disjuntos) não ocorrem juntos, logo P(A ∩ B) = 0. **II** é correta: P(A) + P(Ā) = 1, pois A e seu complementar esgotam o espaço amostral. **III** é falsa: toda probabilidade está entre **0 e 1** (0% a 100%); o evento certo tem probabilidade 1, e nenhum passa disso. Assim, apenas I e II estão corretas.",
